queries.selection_sql:
begin read only;
set local statement_timeout='5s';
select now() observed_at,id,course_id,provider_id,evidence_id,updated_at,
       value->'deadlines' deadlines,value->>'applied' applied,quote
from pipeline.field_enrich_items
where field='deadline' and state='filled'
order by id desc limit 100;
commit;
